import { memo, useMemo } from "react";

const Child = memo(function Child({ user }) {
  console.log("Child rendered");
  return <h1>{user.name}</h1>;
});

function Parent({ name }) {
  const user = useMemo(() => {
    return { name };
  }, [name]);

  return <Child user={user} />;
}

